import 'package:super_annotations/super_annotations.dart';

@CodeGen()
library example;

@MyAnnotation()
class MyClass {
  MyClass(this.value);
  final String value;
}

class MyAnnotation extends ClassAnnotation {
  const MyAnnotation();
  @override
  void apply(Class target, LibraryBuilder output) {
    output.body.add(Code('// generated code'));
  }
}
